sys_variable_value.value:
(function execute(inputs, outputs) {
 try {
 var reservedFor = inputs.reserved_for
 ? inputs.reserved_for.getValue('name')
 : 'Unknown';
 var workspace = inputs.workspace
 ? inputs.workspace.getValue('workspace_name')
 : 'Unknown';
 var startDate = 'Unknown';
 if (inputs.start_date_time) {
 var gdt = new GlideDateTime();
 gdt.setValue(inputs.start_date_time + '');
 startDate = gdt.getDisplayValue();
 }
 // Build the clickable tracker link + claim prompt
 var trackerLink = '';
 if (inputs.tracker_record) {
 var trackerNumber =
inputs.tracker_record.getValue('number');
 var trackerSysId =
inputs.tracker_record.getUniqueValue();
 var instance = gs.getProperty('glide.servlet.uri');
 var url = instance +
'nav_to.do?uri = x_787189_wrm_reservation_tracker.do' +
 '?sys_id=' + trackerSysId;
trackerLink = '\n📄 Reservation ' + trackerNumber + ': ' +
url +
 '\n👋 Who can claim this one?';
 }
 var message = 'Workspace reservation approved for ' +
reservedFor +
 ' - ' + workspace +
 ' on ' + startDate +
 trackerLink;
 var discord = new discordNotification();
 discord.sendMessage(message, '✅');
 } catch (ex) {
 gs.error('Discord approval error: ' + ex.message);
 }
})(inputs, outputs);

